BEGIN; CREATE TABLE t1(rowid INTEGER PRIMARY KEY, i INTEGER, t TEXT); CREATE TABLE t2(rowid INTEGER PRIMARY KEY, i INTEGER, t TEXT); CREATE TABLE t3(rowid INTEGER PRIMARY KEY, i INTEGER, t TEXT); WITH RECURSIVE c(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM c WHERE n<50000) INSERT INTO t1(rowid,i,t) SELECT n,(n*37)%50000,'one-'||printf('%05d',(n*37)%50000) FROM c; WITH RECURSIVE c(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM c WHERE n<50000) INSERT INTO t2(rowid,i,t) SELECT n,(n*41+3)%50000,'two-'||printf('%05d',(n*41+3)%50000) FROM c; WITH RECURSIVE c(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM c WHERE n<50000) INSERT INTO t3(rowid,i,t) SELECT n,(n*43+7)%50000,'three-'||printf('%05d',(n*43+7)%50000) FROM c; CREATE INDEX i1 ON t1(t); CREATE INDEX i2 ON t2(t); CREATE INDEX i3 ON t3(t); COMMIT;